-------------------
---- HOST-LOCAL ----
-------------------
-- Two files, and the order matters.
--
-- host.lua is this machine's taste: where the external screen stands relative
-- to the laptop. Gitignored, one per machine, seeded from host.example.lua.
--
-- state/screens.lua is this machine's FACTS: which screens exist right now,
-- which workspaces belong to which, and whether the lid is shut. It is
-- generated by scripts/screens.sh and loaded LAST, at the bottom of this
-- file, so it wins over anything above it and survives `hyprctl reload`.
--
-- Lua has no `source =`, so load_optional() does it: it resolves the name
-- against the directory of this config file (~ is NOT expanded) and skips a
-- file that is not there instead of raising an error. That is deliberate: a
-- missing sourced file used to put an error banner on screen.
local config_dir = debug.getinfo(1, "S").source:match("^@(.*)/[^/]*$") or "."

local function load_optional(name)
    local path = config_dir .. "/" .. name
    local f = io.open(path, "r")
    if f then
        f:close()
        dofile(path)
    end
end

load_optional("host.lua")

