-- Disse bruges til dine keybindings (små bogstaver)
local terminal    = "alacritty"
local editor      = "helix"
local fileManager = "alacritty -e spf"
local menu        = "rofi -show drun"
-- Zen er pakken zen-browser-bin fra AUR (se group_vars/laptops.yml i
-- Ansible-repoet), så den startes som et almindeligt kommandonavn.
local browser     = "zen-browser"

-------------------
---- AUTOSTART ----
-------------------
hl.on("hyprland.start", function()
    hl.exec_cmd("waybar")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("sleep 1 && waypaper --restore")
    hl.exec_cmd("dunst")
    hl.exec_cmd("hypridle")
    -- Clipboard history: one watcher per content type, both feeding cliphist.
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    -- On-screen display for the volume and brightness keys below.
    hl.exec_cmd("swayosd-server")
    -- Adwaita is an XCursor theme, so force Hyprland to select it explicitly.
    -- This prevents an installed Hyprcursor theme from becoming the fallback.
    hl.exec_cmd("hyprctl setcursor Adwaita 24")
    -- rclone mounts are handled by systemd user services (rclone-dropbox.service,
    -- rclone-onedrive.service) — see the systemd/ stow package.
    -- SeaDrive (Seafile virtual drive) is a GUI tray app, so it autostarts here
    -- rather than as a systemd user service: it needs the graphical session and
    -- waybar's tray. It holds the FUSE mount at ~/SeaDrive for as long as it runs.
    hl.exec_cmd("seadrive-gui")
    -- Work out the screens before anything else opens a window, and keep watching
    -- for a cable. screens.sh also picks the workspace to start on: the external
    -- when docked, the panel when alone.
    hl.exec_cmd("~/.config/hypr/scripts/screens.sh startup")
    hl.exec_cmd("~/.config/hypr/scripts/screens-watch.py")
end)

