-----------------------
---- LOOK AND FEEL ----
-----------------------
-- TUI flavour: windows are panes, not cards. Square corners, a flat one-pixel
-- rule instead of a gradient, no shadow, and only enough gap to tell two
-- panes apart.
hl.config({
    general = {
        layout = "dwindle",
        gaps_in = 4,
        gaps_out = 8,
        border_size = 1,
        col = {
            active_border   = "rgb(88c0d0)",
            inactive_border = "rgb(4c566a)",
        },
        resize_on_border = true,
        allow_tearing = false,
    },

    decoration = {
        rounding = 0,
        active_opacity = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled = false,
        },

        blur = {
            enabled = false,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Nothing moves: windows and layers (bar, launcher, notifications) appear in
-- place, and only a short fade keeps a change from looking like a glitch.
-- Speed is in tenths of a second, so 2 is 200 ms.
hl.curve("easeOut", { type = "bezier", points = { {0.0, 0.9}, {0.1, 1.0} } })

hl.animation({ leaf = "windows",          enabled = false })
hl.animation({ leaf = "layers",           enabled = false })
hl.animation({ leaf = "fade",             enabled = true, speed = 2, bezier = "easeOut" })
hl.animation({ leaf = "workspaces",       enabled = true, speed = 2, bezier = "easeOut", style = "fade" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 2, bezier = "easeOut", style = "fade" })

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------
hl.window_rule({
    name  = "alacritty-opacity",
    match = { class = "^(Alacritty)$" },
    opacity = "0.9 0.8",
})
hl.window_rule({
    name  = "capture-popup",
    match = { title = "^(capture)$" },
    float  = true,
    size   = "600 80",
    center = true,
})
-- The launcher should appear, not arrive. windowsIn above slides every new
-- window in, and on rofi that reads as a GUI animation on something that is
-- meant to feel like a terminal prompt.
hl.window_rule({
    name  = "rofi-no-anim",
    match = { class = "^([Rr]ofi)$" },
    no_anim = true,
})

hl.window_rule({
    name  = "blueman-float",
    match = { class = "^(blueman-manager)$" },
    float = true,
})
hl.window_rule({
    name  = "nm-connection-editor-float",
    match = { class = "^(nm-connection-editor)$" },
    float = true,
})
hl.window_rule({
    name  = "nm-applet-float",
    match = { class = "^(nm-applet)$" },
    float = true,
})
hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

hl.config({
    dwindle = {
        preserve_split = true,
    },
})

hl.config({
    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo = true,
        vrr = 2,
    },
})

hl.config({
    cursor = {
        no_hardware_cursors = true,
    },
})

hl.config({
    input = {
        kb_layout = "dk",
        follow_mouse = 1,
        sensitivity = 0.3,
        accel_profile = "flat",
        touchpad = {
            natural_scroll = true,
            disable_while_typing = true,
        },
    },
})

-- Resize windows with Super + Shift + HJKL
hl.bind("SUPER + SHIFT + h", hl.dsp.window.resize({ x = -20, y = 0,   relative = true }), { repeating = true })
hl.bind("SUPER + SHIFT + l", hl.dsp.window.resize({ x = 20,  y = 0,   relative = true }), { repeating = true })
hl.bind("SUPER + SHIFT + k", hl.dsp.window.resize({ x = 0,   y = -20, relative = true }), { repeating = true })
hl.bind("SUPER + SHIFT + j", hl.dsp.window.resize({ x = 0,   y = 20,  relative = true }), { repeating = true })

---------------------
---- KEYBINDINGS ----
---------------------
local mainMod = "SUPER"

-- System binds
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exit())
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd("alacritty -e tjek"))
-- super+SHIFT+M is exit, plain super+M was free.
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("alacritty -e ncspot"))
-- SHIFT on purpose: on a 65% board (the CK65) Escape is the key left of 1,
-- so a plain super+Escape was one slip away from super+1 and suspended
-- x220-2 mid-work (2026-10-25).
hl.bind(mainMod .. " + SHIFT + Escape", hl.dsp.exec_cmd("hyprlock & systemctl suspend"))

-- Fokus (HJKL)
hl.bind(mainMod .. " + h", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + l", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + k", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + j", hl.dsp.focus({ direction = "down" }))

-- Fokus (piletaster)
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Skift Workspace
-- Move window to workspace
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

hl.bind("SUPER + S",         hl.dsp.workspace.toggle_special("special"))
hl.bind("SUPER + SHIFT + S", hl.dsp.window.move({ workspace = "special" }))

-- Multimedia taster
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("swayosd-client --output-volume raise"),       { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("swayosd-client --output-volume lower"),       { locked = true, repeating = true })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("swayosd-client --output-volume mute-toggle"), { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("swayosd-client --input-volume mute-toggle"),  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("swayosd-client --brightness raise"),          { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("swayosd-client --brightness lower"),          { locked = true, repeating = true })

-- Lid
-- Closing the lid hands the session to an external screen instead of
-- stranding workspaces on a panel nobody can see. Does nothing when the
-- laptop is alone, so logind still suspends as usual. See scripts/lid.sh.
hl.bind("switch:on:Lid Switch",  hl.dsp.exec_cmd("~/.config/hypr/scripts/lid.sh close"), { locked = true })
hl.bind("switch:off:Lid Switch", hl.dsp.exec_cmd("~/.config/hypr/scripts/lid.sh open"),  { locked = true })

-- Mus integration
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Obsidian quick capture
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd("alacritty --title capture -e fish ~/.config/hypr/obsidian-capture.fish"))

-- Andet
hl.unbind("mouse:274")
hl.bind("Print", hl.dsp.exec_cmd("grim ~/Pictures/screenshot-$(date +%Y%m%d-%H%M%S).png"))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd([[grim -g "$(slurp)" ~/Pictures/screenshot-$(date +%Y%m%d-%H%M%S).png]]))
hl.bind("CTRL + SHIFT + Print", hl.dsp.exec_cmd([[grim -g "$(slurp)" - | wl-copy]]))
-- Annotate: the shot opens in satty, which saves to ~/Pictures and copies.
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd([[grim -g "$(slurp)" - | satty --filename - --output-filename ~/Pictures/screenshot-$(date +%Y%m%d-%H%M%S).png --early-exit --copy-command wl-copy]]))

-- Clipboard history and colour picker
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("~/.config/hypr/scripts/clipmenu.sh"))
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd("hyprpicker -a"))

--------------------
---- SCREEN FACTS ----
--------------------
-- LAST on purpose. Generated by scripts/screens.sh from what is actually
-- plugged in and whether the lid is shut, so a reload can no longer resurrect
-- a panel behind a closed lid or strand the workspaces that belong on it.
-- Never edit by hand; it is rewritten on every screen change.
load_optional("state/screens.lua")
